 normalized:=c;normalized.ContentBase64="";raw,_:=json.Marshal(struct{Alias string;Command DriveCommand;Bytes int}{alias,normalized,len(data)});sum:=sha256.Sum256(raw);return data,hex.EncodeToString(sum[:]),nil
