func(m *Manager)driveLedgerPath()string{return filepath.Join(filepath.Dir(m.settingsPath()),"lexopen-drive-commands.json")}
func(m *Manager)driveLedger()(driveCommandLedger,error){p:=m.driveLedgerPath();st,e:=os.Lstat(p);if os.IsNotExist(e){return driveCommandLedger{Schema:"lexopen-drive-commands.v1",Records:map[string]*driveCommandRecord{}},nil};if e!=nil||!st.Mode().IsRegular()||st.Mode().Perm()!=0600||st.Size()>16<<20{return driveCommandLedger{},driveErr(503,"drive_ledger_unavailable")};raw,e:=os.ReadFile(p);if e!=nil{return driveCommandLedger{},driveErr(503,"drive_ledger_unavailable")};var ledger driveCommandLedger;d:=json.NewDecoder(bytes.NewReader(raw));d.DisallowUnknownFields();if d.Decode(&ledger)!=nil||d.Decode(new(any))!=io.EOF||ledger.Schema!="lexopen-drive-commands.v1"||ledger.Records==nil||len(ledger.Records)>10000{return driveCommandLedger{},driveErr(503,"drive_ledger_unavailable")};for id,r:=range ledger.Records{if r==nil||id!=r.Command.RequestID||!lexopenDriveRequestID.MatchString(id)||!lexopenDriveAlias.MatchString(r.Alias)||!lexopenDriveHex.MatchString(r.Hash)||!lexopenDriveHex.MatchString(r.Command.ContextKey)||!lexopenDriveHex.MatchString(r.Command.BindingRevision)||(r.State!="preparing"&&r.State!="executing"&&r.State!="unknown"&&r.State!="failed"&&r.State!="drive_verified")||r.Command.ContentBase64!=""{return driveCommandLedger{},driveErr(503,"drive_ledger_unavailable")}};return ledger,nil}
func(m *Manager)driveSaveLedger(ledger driveCommandLedger)error{raw,e:=json.Marshal(ledger);if e!=nil||len(raw)>16<<20{return driveErr(503,"drive_ledger_unavailable")};dir:=filepath.Dir(m.driveLedgerPath());if e=os.MkdirAll(dir,0700);e!=nil{return driveErr(503,"drive_ledger_unavailable")};f,e:=os.CreateTemp(dir,".drive-commands-*");if e!=nil{return driveErr(503,"drive_ledger_unavailable")};defer os.Remove(f.Name());if e=f.Chmod(0600);e==nil{_,e=f.Write(raw)};if e==nil{e=f.Sync()};closeErr:=f.Close();if e!=nil||closeErr!=nil{return driveErr(503,"drive_ledger_unavailable")};if e=os.Rename(f.Name(),m.driveLedgerPath());e!=nil{return driveErr(503,"drive_ledger_unavailable")};directory,e:=os.Open(dir);if e!=nil{return driveErr(503,"drive_ledger_unavailable")};defer directory.Close();if directory.Sync()!=nil{return driveErr(503,"drive_ledger_unavailable")};return nil}
func driveStoredResult(r *driveCommandRecord)DriveCommandResult{state:=r.State;if state=="executing"{state="unknown"};if state=="preparing"{state="failed"};code:=r.Code;if r.State=="preparing"{code="drive_preparation_interrupted"};return DriveCommandResult{State:state,RequestID:r.Command.RequestID,Receipt:r.Receipt,Code:code,ContextKey:r.Command.ContextKey,AccountRevision:r.Command.BindingRevision,Alias:r.Alias}}
func(m *Manager)LexOpenDriveCommandStatus(alias,id string)(DriveCommandResult,error){if !lexopenDriveAlias.MatchString(alias)||!lexopenDriveRequestID.MatchString(id){return DriveCommandResult{},driveErr(400,"drive_request_invalid")};m.driveMu.Lock();defer m.driveMu.Unlock();l,e:=m.driveLedger();if e!=nil{return DriveCommandResult{},e};r:=l.Records[id];if r==nil||r.Alias!=alias{return DriveCommandResult{State:"not_found",RequestID:id},nil};result:=driveStoredResult(r);if r.State=="preparing"&&m.driveActive[alias]{result.State="unknown";result.Code="drive_request_in_progress"};return result,nil}
type driveFile struct{ID string `json:"id"`;Name string `json:"name"`;MIME string `json:"mimeType"`;Parents []string `json:"parents"`;Trashed bool `json:"trashed"`;DriveID string `json:"driveId"`;Version string `json:"version"`;Size string `json:"size"`;SHA256 string `json:"sha256Checksum"`;AppProperties map[string]string `json:"appProperties"`;Capabilities struct{CanAddChildren bool `json:"canAddChildren"`;CanEdit bool `json:"canEdit"`} `json:"capabilities"`}
func driveGetFile(ctx context.Context,token,id string)(driveFile,error){target:="https://www.googleapis.com/drive/v3/files/"+url.PathEscape(id)+"?fields="+url.QueryEscape("id,name,mimeType,parents,trashed,driveId,version,size,sha256Checksum,appProperties,capabilities(canAddChildren,canEdit)");raw,_,e:=driveHTTP(ctx,token,"GET",target,nil,"",65536);if e!=nil{return driveFile{},e};var f driveFile;if json.Unmarshal(raw,&f)!=nil||!lexopenDriveID.MatchString(f.ID){return driveFile{},driveErr(502,"drive_unavailable")};return f,nil}
