func(m *Manager)driveKnownFailure(l driveCommandLedger,r *driveCommandRecord,e error)error{r.State="failed";r.Code="drive_unavailable";if typed,ok:=e.(*DriveError);ok{r.Code=typed.Code};if m.driveSaveLedger(l)!=nil{return driveErr(503,"drive_ledger_unavailable")};return e}
