 data,hash,e:=driveCommandData(alias,c);if e!=nil{return DriveCommandResult{},e};m.driveMu.Lock();defer m.driveMu.Unlock();ledger,e:=m.driveLedger();if e!=nil{return DriveCommandResult{},e};if old:=ledger.Records[c.RequestID];old!=nil{if old.Alias!=alias||old.Hash!=hash{return DriveCommandResult{},driveErr(409,"drive_request_conflict")};result:=driveStoredResult(old);if old.State=="preparing"&&m.driveActive[alias]{return DriveCommandResult{},driveErr(409,"drive_outcome_unknown")};if result.State=="drive_verified"{return result,nil};if result.State=="unknown"{return DriveCommandResult{},driveErr(409,"drive_outcome_unknown")};return result,driveErr(409,"drive_request_consumed")};if m.driveActive[alias]{return DriveCommandResult{},driveErr(409,"drive_outcome_unknown")};for _,r:=range ledger.Records{if r.Alias==alias&&(r.State=="unknown"||r.State=="executing"){return DriveCommandResult{},driveErr(409,"drive_outcome_unknown")}};if len(ledger.Records)>=10000{return DriveCommandResult{},driveErr(503,"drive_ledger_unavailable")};status,e:=m.LexOpenDriveStatus(alias);if e!=nil{return DriveCommandResult{},e};if !status.CanManageFiles{return DriveCommandResult{},driveErr(403,"drive_manage_required")};if status.AccountRevision!=c.BindingRevision{return DriveCommandResult{},driveErr(409,"drive_account_changed")};saved:=c;saved.ContentBase64="";r:=&driveCommandRecord{Alias:alias,Hash:hash,State:"preparing",Command:saved,Bytes:len(data)};ledger.Records[c.RequestID]=r;if m.driveSaveLedger(ledger)!=nil{return DriveCommandResult{},driveErr(503,"drive_ledger_unavailable")}
