 meta:=map[string]any{"id":id,"name":c.Name,"parents":[]string{r.ParentID},"appProperties":map[string]string{"lexopenRequest":r.Hash}};mimeType:=c.MIME;if c.Action=="create_folder"{mimeType="application/vnd.google-apps.folder"};meta["mimeType"]=mimeType;raw,_:=json.Marshal(meta);target:="https://www.googleapis.com/drive/v3/files?fields=id";ctype:="application/json";payload:=raw;if c.Action!="create_folder"{var body bytes.Buffer;w:=multipart.NewWriter(&body);h:=textproto.MIMEHeader{};h.Set("Content-Type","application/json; charset=UTF-8");part,_:=w.CreatePart(h);part.Write(raw);h=textproto.MIMEHeader{};h.Set("Content-Type",c.MIME);part,_=w.CreatePart(h);part.Write(data);w.Close();ctype="multipart/related; boundary="+w.Boundary();payload=body.Bytes();target="https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id"};_,_,e=driveHTTP(ctx,token,"POST",target,bytes.NewReader(payload),ctype,65536)
